import io
import sys
from unittest import mock

import pytest

import tui


class _FakeStdin:
    """Stand-in for sys.stdin: never touches the real terminal."""

    def __init__(self, chars):
        self._chars = list(chars)
        self.reads = []

    def fileno(self):
        return 0

    def read(self, n=1):
        ch = self._chars.pop(0)
        self.reads.append(ch)
        return ch


class _Harness:
    """Drives tui.main() through a scripted sequence of (char, clock) steps.

    Each step is a tuple ``(char_or_None, monotonic_value)``. When ``char`` is
    None the fake ``select.select`` reports nothing ready for that iteration.
    """

    def __init__(self, steps):
        self.steps = list(steps)
        self.index = 0
        self.stdin = _FakeStdin([c for c, _ in steps if c is not None])
        self.stdout = io.StringIO()
        self.engine = mock.Mock()
        self.engine.close = mock.Mock()
        self.engine.key_down = mock.Mock()
        self.engine.key_up = mock.Mock()
        self.engine_factory = mock.Mock(return_value=self.engine)
        self.termios = mock.Mock()
        self.termios.TCSADRAIN = "TCSADRAIN-sentinel"
        self.termios.tcgetattr = mock.Mock(return_value=["saved-attrs"])
        self.termios.tcsetattr = mock.Mock()
        self.tty = mock.Mock()
        self.on_state_change = None

    def _select(self, rlist, wlist, xlist, timeout):
        if self.index >= len(self.steps):
            raise AssertionError("main() ran past the end of the script")
        char, _clock = self.steps[self.index]
        return ([self.stdin], [], []) if char is not None else ([], [], [])

    def _monotonic(self):
        if self.index >= len(self.steps):
            raise AssertionError("main() ran past the end of the script")
        _char, clock = self.steps[self.index]
        self.index += 1
        return clock

    def run(self):
        def factory(on_state_change):
            self.on_state_change = on_state_change
            return self.engine

        self.engine_factory.side_effect = factory
        fake_sys = mock.Mock()
        fake_sys.stdin = self.stdin
        fake_sys.stdout = self.stdout
        with mock.patch.object(tui, "NoteEngine", self.engine_factory), \
                mock.patch.object(tui, "termios", self.termios), \
                mock.patch.object(tui, "tty", self.tty), \
                mock.patch.object(tui, "sys", fake_sys), \
                mock.patch.object(tui.select, "select", self._select), \
                mock.patch.object(tui.time, "monotonic", self._monotonic), \
                mock.patch("builtins.print", lambda *a, **k: None):
            return tui.main()


