def test_main_releases_key_after_release_timeout():
    # meridian: unit_id=28faeb62248a requirement=3-4
    late = tui.RELEASE_TIMEOUT_SECONDS + 0.5
    harness = _Harness([("a", 0.0), (None, late), ("q", late + 0.1)])
    harness.run()
    harness.engine.key_down.assert_called_once_with("a")
    harness.engine.key_up.assert_called_once_with("a")


def test_main_does_not_release_key_before_timeout():
    # meridian: unit_id=28faeb62248a requirement=3-4
    early = tui.RELEASE_TIMEOUT_SECONDS - 0.01
    harness = _Harness([("a", 0.0), (None, early), ("q", early + 0.001)])
    harness.run()
    harness.engine.key_up.assert_not_called()


def test_main_state_change_callback_updates_and_draws():
    # meridian: unit_id=28faeb62248a requirement=3-4
    harness = _Harness([("q", 0.0)])
    harness.run()
    assert harness.on_state_change is not None
    drawn = []
    with mock.patch.object(tui, "_draw", lambda active: drawn.append(set(active))):
        harness.on_state_change("a", True)
        harness.on_state_change("s", True)
        harness.on_state_change("a", False)
    assert drawn == [{"a"}, {"a", "s"}, {"s"}]
